// th14_s4_w06 — TH14 v1.00b Stage 4 道中 MainSub02 (st04.ecl.txt:1091-1114)
// 入口：MainSub02 段 1091-1114；闭包：MainSub02b / ECir02 / ECir02_at / GirlA01(b) / GirlA01_at / GirlA01_at2。

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// TH14 弹型词表（合成映射：源 type0-23 同号；见 bullet-types.md）
const TH14_RICE: int = 480;      // 源 type 8（色 6 由调用处给）
const TH14_KUNAI: int = 496;     // 源 type 9
const TH14_BIG_BALL: int = 640;  // 源 type 18

// 源 ECir02_at: etEx WAIT(60) 后 VELTIME(a=60, r=%B, s=-999999 保留弹角)。
// 目标按“进入时保存方向”的原语义沿当前弹向加速：极坐标 set_accel 即 speed+=delta、角度不动。
xformdef ECIR_RAMP(target: fx) {
    wait(60);
    set_accel((target - 0.2fx) / 60fx);
    wait(60);
    stop_fx();
}

// 源 GirlA01_at2: etEx WAIT(120) 后 VELTIME(a=60, r=1+2*RANDF, s=90deg 字面角)。
// 目标用固定方向的笛卡尔加速度，保留每颗弹自己的起角与横向分量。
xformdef GIRL_RAMP(target: fx) {
    wait(120);
    set_gravity(0fx, (target - 1fx) / 60fx);
    wait(60);
    stop_fx();
}

// ── GirlA01 / GirlA01b ──────────────────────────────────────────────────────
// 源 GirlA01_at2（465-516）：每轮 wait(3+RAND%25) 后发 5 路米弹；DIFF>=1 且
// A%B==0 时再发 3 路苦无。B=diffI(3,4,2,1)，轮末等待 E25/N20/H15/L10。
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    var every: int = 3;
    var gap: int = 25;
    if rank == 1 { every = 4; gap = 20; }
    if rank == 2 { every = 2; gap = 15; }
    if rank == 3 { every = 1; gap = 10; }
    var a: int = 0;                                  // 源 $A
    loop {
        wait(3 + rand(25));                          // 源 wait(3 + ($RAND % 25))
        // 源 etNew(0)/etSprite(8,6)/etAim(1)/etCount(5,1)/etAngle(90deg,1deg)/etSpeed(1,1)；
        // etEx: ANIM(1) 出生表现按口径省略，WAIT 120 + VELTIME 60 进 GIRL_RAMP。
        var u: fx = (rand(65536) - 32768) as fx / 65536 + 0.5fx;     // 源 %RANDF ∈ [0,1)
        sh_reset(0);
        sh_sprite(0, TH14_RICE, 6);
        sh_ring(0, 0);                               // etAim(1) 固定方向扇形
        sh_count(0, 5, 1);
        sh_speed(0, 1fx, 0fx);
        sh_angle(0, 90deg, 1deg);
        sh_xform(0, GIRL_RAMP(1fx + 2fx * u));       // 源 r=(2.0*%RANDF)+1.0
        sh_fire(0);
        if rank >= 1 && a % every == 0 {             // 源 unless ($DIFF>=1 && A%B==0)
            var su: fx = (rand(65536) - 32768) as fx / 32768;         // 源 %RANDF2 ∈ [-1,1)
            var off: int = (5461fx * su) as int;                     // 30deg 幅度
            sh_reset(1);
            sh_sprite(1, TH14_KUNAI, 6);
            sh_ring(1, 0);
            sh_count(1, 3, 1);
            sh_speed(1, 1.5fx, 0fx);
            sh_angle(1, 90deg + (off as angle), 45deg);
            sh_fire(1);
        }
        a = a + 1;
        wait(gap);
    }
}

// 源 GirlA01_at（448-463）：框 24/16 → 半径 12/8；moveVel(22.5deg,4)、
// moveVelTime(120,mode1=二次加速,-11.25deg,3)、wait(120)、moveVelTime(60,mode4=二次减速,11.25deg,4)，之后常驻。
// 镜像在写入点换算为关于竖直轴的角度反射（源 enmCreateM 子镜像=1）。
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);
    set_hurtbox(12fx);
    spawn girl_fire();                               // 源 @GirlA01_at2() async
    var a0: angle = 4096bam;                         // 22.5deg
    var a1: angle = -2048bam;                        // -11.25deg
    var a2: angle = 2048bam;                         // 11.25deg
    if mirror != 0 {
        a0 = 180deg - a0;
        a1 = 180deg - a1;
        a2 = 180deg - a2;
    }
    move_vel(0, a0, 4fx, EASE_LINEAR);
    move_vel(120, a1, 3fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a2, 4fx, EASE_QUAD_OUT);
    // 源之后 wait(1000) 常驻；出界即结束主任务（近似原生屏外回收），发弹任务随 owner 一并停止。
    loop {
        wait(1);
        if $self_x > 256fx || $self_x < -256fx || $self_y > 512fx || $self_y < -64fx { return; }
    }
}

// ── ECir02 ──────────────────────────────────────────────────────────────────
// 源 ECir02_at（311-361）：wait(10)；每轮 8 连发（间隔 1 帧），VELTIME 目标 1.0+0.4i；
// 轮末等待 E60/N50/H50/L40；轮数 C=diffI(1,1,2,8)；路数 E1 其余 8。
async sub ecir_fire() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var passes: int = 8;
    var count: int = 8;
    var gap: int = 40;
    if rank == 0 { passes = 1; count = 1; gap = 60; }
    if rank == 1 { passes = 1; gap = 50; }
    if rank == 2 { passes = 2; gap = 50; }
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 4);                  // 源 etSprite(0,18,4)
    sh_ring(0, 0);                                   // 源 etAim(0,1) 固定方向扇形
    sh_count(0, count, 1);
    sh_speed(0, 0.2fx, 0fx);
    while passes > 0 {
        sh_angle(0, aim_player(), 20deg);            // 源每轮 etAngle(%ANGLE_PLAYER, 20deg) 取一次
        for i in 0..8 {
            sh_xform(0, ECIR_RAMP(1fx + (i as fx) * 0.4fx));   // 源 %B: 1.0,1.4,...,3.8
            sh_fire(0);
            wait(1);
        }
        wait(gap);
        passes = passes - 1;
    }
}

// 源 ECir02（276-309）：框 24/16 → 12/8；movePosRel(-192*A,0) 由创建坐标给出；
// 两条 moveBezierRel 按 Hermite 槽逐帧写 REL 位置（起点=当前层位置，中点为终点，首尾为归一化时间切线）。
// 源 flagSet(15)/anmScale/alpha/color 的出生窗口按已批准出生表现口径省略。
async sub ecir(a: fx) {
    set_invuln(65535);
    set_hitbox(8fx);
    set_hurtbox(12fx);
    var x0: fx = $self_x;
    var y0: fx = $self_y;
    var x1: fx = x0 + 160fx * a;
    var y1: fx = 128fx;
    // 源 moveBezierRel(120, (256a,-30), (160a,128), (0,0))
    hermite_start(0, x0, x1, 256fx * a, 0fx, 120);
    hermite_start(1, y0, y1, -30fx, 0fx, 120);
    for i in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 源 wait(120) 与首条曲线同刻结束；随后 moveBezierRel(120, (0,0), (-220a,192), (-200a,-228))
    var x2: fx = x1 - 220fx * a;
    var y2: fx = y1 + 192fx;
    hermite_start(0, x1, x2, 0fx, -200fx * a, 120);
    hermite_start(1, y1, y2, 0fx, -228fx, 120);
    spawn ecir_fire();                               // 源 @ECir02_at() async
    for j in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    loop { wait(1000); }                             // 源 wait(1000) 常驻
}

// ── 排程 ────────────────────────────────────────────────────────────────────
// 源 MainSub02b（1118-1127）：三只 ECir02 在 0/280/460，镜像 1/0/1（A=-1/+1/-1）。
async sub ecir_wave() {
    _ = spawn_enemy(192fx, 0fx, 150, 0, 0, 0, ecir(-1fx));
    wait(100);
    wait(180);
    _ = spawn_enemy(-192fx, 0fx, 150, 0, 0, 0, ecir(1fx));
    wait(180);
    _ = spawn_enemy(192fx, 0fx, 150, 0, 0, 0, ecir(-1fx));
}

// 源 MainSub02_868/_1236 两个 $C/$D=10 的循环：每 20 帧一左一右、先后两组 GirlA01b/GirlA01，
// 镜像 0/1 交替（GirlA01b 与 GirlA01 仅主动画/掉落不同，按口径合并）。
sub girl_batch() {
    var n: int = 10;
    while n > 0 {
        _ = spawn_enemy(-224fx, 32fx, 60, 0, 0, 0, girl(0));
        _ = spawn_enemy(224fx, 32fx, 60, 0, 0, 0, girl(1));
        wait(10);
        _ = spawn_enemy(-224fx, 32fx, 60, 0, 0, 0, girl(0));
        _ = spawn_enemy(224fx, 32fx, 60, 0, 0, 0, girl(1));
        wait(10);
        n = n - 1;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn ecir_wave();                               // 源 1091 @MainSub02b() async（与 GirlA 循环同时开始）
    girl_batch();                                    // 源 1092-1102，卡帧 0-200
    wait(180);                                       // 源 1103
    girl_batch();                                    // 源 1104-1114，卡帧 380-580
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
